INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('fishhead','Fishhead','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"fishhead","name":"Fishhead","team":"outsider","ability":"On night (Max Outsiders + 1 - X), Townsfolk abilities yield false info until dusk. You''re sober & healthy. [X Outsiders]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Fishhead (SCP-527 - a.k.a Mr. Fish) has incurred the wrath of Yvith for their incredibly smelly & grotesque head.","summaryBullets":["Uhh... Fishhead... he.. uh..s..","He makes the Outsider count arbitrary... I gues...","And... uhh... also makes Townsfolk information false...","The more Outsiders there are... the early he... does ... it...","He''s sober and healthy... so this can''t... be... avoided... unless dead...","{{i|Also he can appear and modify Outsider count even in Base 0 Outsiders **LMAO**.}}"],"howToRun":["While setting up the game, before putting character tokens in the bag, add or remove any number of Outsider tokens. For the amount of Outsiders then in the bag, place the **{{i|Y}}** reminder on the center of the Grimoire, where **{{i|Y}}** is equal to **(Number of Outsiders on the script plus One minus number of Outsiders in the bag)**.","When the **1/FALSE** reminder token is in the Grimoire, you must give false information whenever a Townsfolk ability prompts you to give information.","Each dusk, subtract one from the Fishhead''s reminder token count. If currently **1/FALSE**, remove it entirely."],"tips":["Since the Fishhead can normally and absolutely bring Outsiders into a game that doesn''t have them at base, be careful about running this, and assure your players if you have any intent of possibility doing this, or not.","On hot summer days, remember to move the Fishhead away from windows, and to clean their enclosure every once in a while."],"quote":"God hates me.","iconBy":"le_nuberto","jinxes":[{"name":"Banshee","align":"good","text":"If the Fishhead''s false info is active and the Demon kills the Banshee, the players still learn that the Banshee has died.","id":"banshee"},{"name":"Prognosticator","align":"good","text":"The prophecy is not effected by the Fishhead.","slug":"prognosticator"},{"name":"Red Sea Stone","align":"good","text":"What ability the Red Sea Stone gets & learns is not effected by the Fishhead.","slug":"red-sea-stone"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Fishhead, where it was originally a joke of a character that took up space existing and breathing my air, use this JSON.\n\nWhile setting up the game, before putting character tokens in the bag, add one extra Outsider character token and remove one Townsfolk character token.\n\nAt any time during the day, the Fishhead can approach the Storyteller privately for a fish joke that must involve at least 2 alive characters. It can feature more characters than that if you choose, regardless if they''re alive, dead, or not in-play.\n\n**Fishhead █~** (Outsider)\nOnce per game, during the day, visit the Storyteller for a fish joke including at least 2 alive characters. [+1 Outsider]\n\n**Reminders:** No ability\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["1/False","2","3","4","5"],"setup":true,"art":"art/fishhead.png","jsonId":"fishhead_scp_fragmented_veil","curata":false}','scp-fragmented-veil/fishhead','published',datetime('now'),datetime('now')),
('loyal-servant','Loyal Servant','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"loyal-servant","name":"Loyal Servant","team":"outsider","ability":"Each night, if good, 1 living Minion may ''accept'' to swap characters & you become evil. At dusk, this is undone if you both live.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-662 is a hand-bell that summons an obedient & loyal servant for whomever rung it.","summaryBullets":["Each night, 1 Minion will wake to decide if they''ll ring the handbell, or not.","If they do, they''ll swap characters with the Loyal Servant as the Loyal Servant becomes evil.","If they don''t, nothing different happens.","The Loyal Servant does not know who rang the handbell, only their character by virtue of swapping with them.","Come dusk, and if the current Loyal Servant has their ability and both of the involved players live, they swap characters back as the original becomes good."],"howToRun":["During each night, if the current Loyal Servant is good, wake any living Minion. Show them the **THIS CHARACTER SELECTED YOU** info token, then the Loyal Servant token. That player either nods their head yes or shakes their head no. Put that player to sleep. If they shook their head no, then nothing happens.","If they nodded their head yes, swap the character tokens of the Minion and Loyal Servant. If a player’s alignment does not match the color of their character token, turn it upside-down {{i|(you will need to do this for the current Loyal Servant)}}. wake the then-Loyal Servant, show them the **YOU ARE** info token, their new character token, a thumbs-down, then put them to sleep. Mark the then-Loyal Servant with the **IS SERVANT** reminder token.","Each dusk, if a Minion is marked **IS SERVANT** and both them and the Living Servant are alive, swap the character tokens of that Minion and the Loyal Servant and make the original Loyal Servant good. If a player’s alignment does not match the color of their character token, turn it upside-down."],"tips":["Due to the amount of Minion swapping going on with this character, Minions with a limited-use ability will refresh it between exchanges {{i|(such as the Assassin)}}, and a Minion with an information-based ability will have to be wary about providing to a player who might not be aligned with the evil team in the end {{i|(such as the Godfather)}}. Be very careful about what Minions you are to include on your scripts for this reason."],"quote":"Forever Mine – S.J.W.","iconBy":"quorglepleegjr","jinxes":[{"name":"Fearmonger","align":"evil","text":"Even if the Fearmonger changes, no new ping is given as long as the target is the same, and there can only be one ping per day.","id":"fearmonger"},{"name":"Godfather","align":"evil","text":"If the Loyal Servant swaps with the Godfather, they don''t learn the in-play Outsiders.","id":"godfather"},{"name":"Chameleon","align":"evil","text":"If the Loyal Servant swaps with the Chameleon, they don''t learn the good player.","id":"chameleon_2tfafullcharacterlist"},{"name":"Governess","align":"evil","text":"If the Loyal Servant swaps with the Chameleon, they don''t learn the good player.","id":"governess_2tfafullcharacterlist"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Loyal Servant, where it was an uncreative mix of Goon and Butler, use this JSON.\n\nAt night, if a player chooses to use their ability on the Loyal Servant and nobody is marked with the Loyal Servant’s **MASTER** reminder, this player immediately becomes the Loyal Servant''s master - mark them with the **MASTER** reminder. Wake the Loyal Servant, point to their master. If this player’s alignment is different from the Loyal Servant’s alignment, rotate the the Loyal Servant’s character token - right side up for good, upside-down for evil - to match this player’s alignment, then also give them a thumbs-up or a thumbs-down {{i|(indicating their new alignment)}}, then put the Loyal Servant to sleep.\n\nDuring a nomination, the Loyal Servant may only have their hand raised to vote if the Master has their hand raised to vote or if the Master''s vote has already been counted {{i|(if they have a Master today)}}.\n\n**Loyal Servant █~** (Outsider)\nEach night, become the alignment of the 1st player to choose you with their ability (you learn who), and tomorrow, you may only vote if they are voting too.\n\n**Reminders:** Master\n**Credit:** Ability: @legitch. Image: @quorglepleegjr\n\n**Jinxes:**\nBoffin: If the Demon has the Loyal Servant ability, they can’t turn good due to this ability.\nCannibal: If the Cannibal gains the Loyal Servant''s ability, the Cannibal learns this.\nOrgan Grinder: If the Organ Grinder is causing eyes closed voting, the Loyal Servant may raise their hand to vote but their vote is only counted if their master voted too.\nPit-Hag: If the Pit-Hag turns an evil player into the Loyal Servant, they can''t turn good due to their own ability.\nRiot: The Loyal Servant cannot nominate their master.\nHuli Jing: If the Huli Jing gains the Loyal Servant ability, they can not turn Good.\nDon Juan: An evil Loyal Servant doesn''t register as an Outsider for the Don Juan''s ability.\nModiste: If the Modiste gains the Loyal Servant ability, they can not turn Good."}],"firstNight":24.622,"otherNight":12.622,"remindersGlobal":["Is Servant"],"setup":false,"firstNightReminder":"Wake a living Minion, show them the ''This character selected you'' token, then the Loyal Servant token. That player either nods their head yes or shakes their head no. If they nodded their head yes, swap the Loyal Servant and that Minion''s characters and make the Loyal Servant evil, wake the Loyal Servant to inform them of their new character and alignment.","otherNightReminder":"Wake a living Minion, show them the ''This character selected you'' token, then the Loyal Servant token. That player either nods their head yes or shakes their head no. If they nodded their head yes, swap the Loyal Servant and that Minion''s characters and make the Loyal Servant evil, wake the Loyal Servant to inform them of their new character and alignment.","art":"art/loyal-servant.png","jsonId":"loyalservant_scp_fragmented_veil","curata":false}','scp-fragmented-veil/loyal-servant','published',datetime('now'),datetime('now')),
('shoe-in','Shoe-In','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"shoe-in","name":"Shoe-In","team":"outsider","ability":"The 1st time the dead equal or outnumber the living, you join the losing team & learn 1 teammate.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1667 is a non-physical contagion that infects footwear, driving anyone in physical contact to enter the pacific ocean, to which no one returns from.","summaryBullets":["The Shoe-In only activates their ability after a few nights have passed - once the dead players equal or outnumber the living.","In the odd event that the Shoe-In is currently evil and good is losing, they will turn good for this occasion.","The Shoe-In''s chance to become evil only occurs once in the game, and if they don''t become evil then, they don''t become evil later.","This does not occur if the Shoe-In is dead or has died that night.","In the situation that the Shoe-In is drunk or poisoned, they do not change alignments, but can learn any player."],"howToRun":["When the number of dead players equals or exceeds the number of alive players and they aren''t marked with the Shoe-In''s **HALF-WAY** reminder token, mark them with the **HALF-WAY** reminder, and if you believe that the Shoe-In''s opposing team is losing, rotate the Shoe-In’s character token - right side up for good, upside-down for evil - to match this player’s alignment. Wake the Shoe-In, give them a thumbs-up or a thumbs-down {{i|(indicating their current alignment)}}. Point to one player on their team. Put the Shoe-In to sleep."],"tips":["It is possible for the Shoe-In to learn themselves from their ability, but it is ill-advised to do this unless both teams are effectively neck & neck."],"quote":"Must... enter... ocean... must... enter... ocean... going for... schwim...","iconBy":"le_nuberto","jinxes":[{"name":"Boffin","align":"evil","text":"If the Demon has the Shoe-In ability, they can’t turn good due to this ability.","id":"boffin"},{"name":"Pit-Hag","align":"evil","text":"If the Pit-Hag turns an evil player into the Shoe-In, they can''t turn good due to their own ability.","id":"pithag"},{"name":"Leviathan","align":"evil","text":"The Shoe-In''s ability instead activates on Night 3 or half of all evil players are dead instead of all players.","id":"leviathan"},{"name":"Matsuraid","align":"evil","text":"The Shoe-In''s ability instead activates on Night 2.","id":"matsuraid_hblreleased"},{"name":"Au’Wre","align":"evil","text":"The Shoe-In''s ability instead activates once the Au''Wre has fully guessed their Minions or half of all evil players are dead instead of all players.","id":"auwre_the_bootleggers_anthology"},{"name":"Huli Jing","align":"evil","text":"If the Huli Jing gains the Shoe-In ability, they can not turn Good.","id":"hulijing_the_bootleggers_anthology"},{"name":"Ketos","align":"evil","text":"The Shoe-In''s ability instead activates when the end is half-way there or half of all evil players are dead instead of all players.","id":"ketos_the_bootleggers_anthology"},{"name":"Don Juan","align":"evil","text":"An evil Shoe-In doesn''t register as an Outsider for the Don Juan''s ability.","id":"donjuan_darkartists_stuff"},{"name":"Modiste","align":"evil","text":"If the Modiste gains the Shoe-In ability, they can not turn Good.","id":"modiste_darkartists_stuff"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Other nights:** If it''s the 1st time the dead equal or outnumber the living, show them the thumbs up good signal of the thumbs down evil signal accordingly to their alignment, then point to a player on their team."}],"firstNight":0,"otherNight":89.1667,"reminders":["Half-way"],"setup":false,"otherNightReminder":"If the dead equal or outnumber the living, show them the thumbs up good signal of the thumbs down evil signal accordingly to their alignment, then point to a player on their team.","art":"art/shoe-in.png","jsonId":"shoein_scp_fragmented_veil","curata":false}','scp-fragmented-veil/shoe-in','published',datetime('now'),datetime('now')),
('laughster','Laughster','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"laughster","name":"Laughster","team":"outsider","ability":"If you weren''t funny today, tonight, a player might die. During the day, you die if & only if you are exceptionally funny.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Laughster''s (SCP-1799 - a.k.a Mr. Laugh) nature is to be funny, even if he doesn''t want to.","summaryBullets":["The Laughster has a metaphorical gun pointed to their head: make people smile and laugh, or people they care about might die.","The Storyteller is the judge of whether the Laughster was funny or not.","The Laughster cannot end their own suffering by conventional methods; attempts to kill the Laughster during the day will fail, making their detrimental ability stick.","... However, if the Laughster is exceptionally funny by the Storyteller''s perspective, they might die right there on the spot."],"howToRun":["At any time {{i|(even at night)}}, if you believe that the Laughster is relatively funny, then you can decide to mark them with the **FUNNY** reminder for as long as you need.","Each night except the first, if the Laughster is not marked with the **FUNNY** reminder, you may choose any player. The chosen player {{i|dies}} - mark them with the **DEAD** reminder.","During the day, if you believe that the Laughster is exceptionally and uncontrollably funny {{i|(to a degree that even you cannot contain your own laughter on purpose)}}, then you can decide to kill the Laughster. Immediately declare that they die. Otherwise, if the Laughster is killed outside of that during the day, they don''t, even by execution."],"tips":["It is best to be forgiving and treat even a slightly funny the Laughster as funny. It can be tough to be funny when one is expected to be, after all.","Don''t be tempted to not smite the Laughster during the day if you find them exceptionally funny despite the in-game circumstances. The Laughster is mostly a joke character meant to liven up games, and should be respected when it''s able to create some comedic moments for players to enjoy.","It is possible for the Laughster''s ability to kill themselves, in-case they have a poor taste in comedy."],"quote":"Get up, you worthless sack of shit... consider this a friendly reminder: GET WITH THE FUCKING PROGRAM.","iconBy":"le_nuberto","jinxes":[{"name":"Lycanthrope","align":"good","text":"The Laughster cannot die to the Lycanthrope.","id":"lycanthrope"},{"name":"Surgeon","align":"evil","text":"The Laughster cannot die to the Surgeon.","id":"surgeon_the_bootleggers_anthology"},{"name":"Heir","align":"evil","text":"The Laughster will fail to take the stead unless they told a really funny joke.","id":"heir_darkartists_stuff"},{"name":"Vigilante","align":"good","text":"The Laughster cannot die to the Vigilante.","id":"vigilante"},{"name":"Corsair","align":"good","text":"The Laughster cannot die to the Corsair.","id":"corsair_hypers_hoard_of_homebrew"}],"firstNight":0,"otherNight":54.1799,"reminders":["Funny","Dead"],"setup":false,"otherNightReminder":"If the Laughster was not funny today: Choose a player not protected from dying tonight. That player might die.","art":"art/laughster.png","jsonId":"laughster_scp_fragmented_veil","curata":false}','scp-fragmented-veil/laughster','published',datetime('now'),datetime('now')),
('immaterial','Immaterial','outsider','legitch',NULL,'','SCP Fragmented Veil','{"slug":"immaterial","name":"Immaterial","team":"outsider","ability":"If anything bad happens to you, it might be on a living neighbour instead. If executed, you might live, and a player dies tonight.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Immaterial (SCP-2428 - a.k.a Mr. Mad) alters the perception of others on them.","summaryBullets":["If something bad happens to the Immaterial, such as death, drunkenness, or poisoning, it might be redirected on another good living neighbour.","Dead or evil neighbours will not be a potential candidate for this.","Occasionally, the Immaterial can survive execution if it succeeds and remain alive, at the cost of redirecting their death onto another player, whom may be of more importance."],"howToRun":["Each time the Immaterial would be effected by any bad action or ability - such as being killed, made drunk, or poisoned - you may choose to have it instead affect one of their living neighbours instead, and move the respective reminder token that signifies that status onto them.","If the Immaterial is executed, you may choose to mark them with the **DODGING** reminder, and declare that player was executed but remains alive {{i|(do not say why.)}}","Each night except the first, if the Immaterial is marked with the **DODGING** reminder, you choose any player not being protected that night. The chosen player dies - mark them with the **DEAD** reminder, then remove the **DODGING** reminder from the Immaterial''s character token."],"quote":"Who? Oh right, me! Where? Oh right, here! Haha... ha... If you don''t mind me asking, but when...","iconBy":"le_nuberto","jinxes":[{"name":"Riot","align":"evil","text":"The Immaterial might not die by nomination, but if nominated, might also kill another teammate.","id":"riot"},{"name":"Heir","align":"evil","text":"If the Immaterial dies on a good player''s stead, they might live but someone dies tonight.","id":"heir_darkartists_stuff"}],"firstNight":0,"otherNight":54.2428,"reminders":["Dodging","Dead"],"setup":false,"otherNightReminder":"If the Immaterial is marked ''Dodging'': Choose a player not protected from dying tonight. That player dies.","art":"art/immaterial.png","jsonId":"immaterial_scp_fragmented_veil","curata":false}','scp-fragmented-veil/immaterial','published',datetime('now'),datetime('now'));
